const wire=$('#wireframe'),track=$('.wire-track'),cards=$$('.wire-card'),dots=$$('[data-wire]');let wi=-1;
function wireIndex(n){if(wi===n)return;wi=n;cards.forEach((c,i)=>c.classList.toggle('active',i===n));dots.forEach((c,i)=>{c.classList.toggle('active',i===n);c.setAttribute('aria-pressed',String(i===n))})}
let raf=false;function scrollUpdate(){raf=false;const h=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=(h?scrollY/h*100:0)+'%';const r=wire.getBoundingClientRect(),travel=wire.offsetHeight-innerHeight,progress=Math.min(1,Math.max(0,-r.top/travel));const width=cards[0].offsetWidth,gap=parseFloat(getComputedStyle(track).gap)||55;track.style.transform=`translateX(${-progress*4*(width+gap)}px)`;wireIndex(Math.round(progress*4))}addEventListener('scroll',()=>{if(!raf){raf=true;requestAnimationFrame(scrollUpdate)}},{passive:true});addEventListener('resize',scrollUpdate);scrollUpdate();dots.forEach((b,i)=>b.onclick=()=>{window.scrollTo({top:scrollY+wire.getBoundingClientRect().top+(wire.offsetHeight-innerHeight)*i/4,behavior:reduced?'instant':'smooth'})});
const slides=[5,17,18,11,23];let si=0,playing=!reduced,elapsed=0,last=performance.now(),inview=false;const auto=$('.autoplay');new IntersectionObserver(es=>inview=es[0].isIntersecting,{threshold:.15}).observe(auto);function showSlide(n){si=n;$('.auto-phone img').src=`assets/waiting/ui-${slides[n]}.png`;$$('[data-slide]').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-pressed',String(i===n))});elapsed=0}function autoButton(){const b=$('#auto-toggle');b.textContent=playing?'暂停自动播放 Ⅱ':'开始自动播放 ▷';b.setAttribute('aria-pressed',String(playing))}$$('[data-slide]').forEach(b=>b.onclick=()=>showSlide(+b.dataset.slide));$('#auto-toggle').onclick=()=>{playing=!playing;autoButton()};autoButton();setInterval(()=>{const now=performance.now(),dt=now-last;last=now;if(playing&&inview&&!document.hidden){elapsed+=dt;if(elapsed>4500)showSlide((si+1)%slides.length)}$('.auto-progress i').style.width=Math.min(100,elapsed/45)+'%'},100);
