const defaults=[{id:'teddy',name:'Teddy Bear',story:'A gift that quietly stayed with me through university. 小熊肚子里曾装着糖果，也装着那一天的关心。',status:'Waiting',photo:'assets/waiting/p2-1.jpg'},{id:'bracelet',name:'Bead Bracelet',story:'2023 年的祈愿，三年的陪伴。断开之后，我还是想继续戴着它。',status:'Waiting',photo:'assets/waiting/p2-5.jpg'},{id:'outfit',name:'Cooking Outfit',story:'在爱丁堡的一年，从第一顿饭开始陪着我的衣服。',status:'Waiting',photo:'assets/waiting/p2-2.jpg'}];let objects;try{objects=JSON.parse(localStorage.getItem('waiting-room-objects-v1'));if(!Array.isArray(objects))objects=structuredClone(defaults)}catch{objects=structuredClone(defaults)}let page='home',filter='All',query='';const root=$('#prototype');const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
