function render(){root.innerHTML=`<div class="proto-top"><h3>${page==='archive'?'Archive':page==='add'?'Meet the Object':page==='detail'?'Object Passport':'Your Waiting Room'}</h3><p>${page==='archive'?'Stories of objects that have left limbo.':'A place for objects you are not ready to decide on yet.'}</p></div><div class="proto-body"></div><nav class="proto-nav" aria-label="原型底部导航"><button data-go="home">⌂<br>WAITING</button><button class="add" data-go="add" aria-label="添加物品">＋</button><button data-go="archive">▤<br>ARCHIVE</button></nav>`;$$('[data-go]',root).forEach(b=>b.onclick=()=>{page=b.dataset.go;render()});const body=$('.proto-body',root);if(page==='add'){body.innerHTML='<form id="object-form"><label for="object-name">What do you call the object? / 物品名称</label><input id="object-name" name="name" required maxlength="60" placeholder="例如：陪我搬家的杯子"><label for="object-story">How did it come into your life? / 它的故事</label><textarea id="object-story" name="story" required maxlength="1200" placeholder="记下一段回忆，不需要马上决定。"></textarea><label for="object-time">How long have you had it? / 陪伴时间</label><input id="object-time" name="time" maxlength="60" placeholder="例如：三年"><button class="proto-btn" type="submit">放进等待室 →</button><p class="proto-note">You don’t have to decide yet.</p></form>';$('form',body).onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),name=String(fd.get('name')).trim(),story=String(fd.get('story')).trim();if(!name||!story)return;objects.unshift({id:String(Date.now()),name,story,time:String(fd.get('time')),status:'Waiting',photo:''});save();page='home';render()};return}if(page==='detail'){const o=objects.find(x=>x.id===selected);if(!o){page='home';render();return}body.innerHTML=`<button class="proto-back">← 返回物品</button>${o.photo?`<img class="proto-photo" src="${esc(o.photo)}" alt="${esc(o.name)}">`:''}<h3 style="margin-top:20px">${esc(o.name)}</h3><span class="proto-status">${esc(o.status)}</span><p class="proto-note">${esc(o.story)}</p>${o.time?`<p class="proto-note">在一起：${esc(o.time)}</p>`:''}<label for="future-select">它的下一段旅程</label><select id="future-select"><option value="Waiting">继续等待 / Waiting</option><option value="Kept">留下 / Kept</option><option value="Repaired">修复 / Repaired</option><option value="Passed on">转赠 / Passed on</option><option value="Let go">告别 / Let go</option></select><button class="proto-btn" id="save-future">保存这次决定</button>`;$('.proto-back',body).onclick=()=>{page=o.status==='Waiting'?'home':'archive';render()};$('#future-select').value=o.status;$('#save-future').onclick=()=>{o.status=$('#future-select').value;save();page=o.status==='Waiting'?'home':'archive';render()};return}if(page==='archive'){body.innerHTML=`<input type="search" aria-label="搜索归档物品" placeholder="Search stories…" value="${esc(query)}"><div class="proto-filter">${['All','Kept','Repaired','Passed on','Let go'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div class="proto-list"></div>`;$('input',body).oninput=e=>{query=e.target.value;drawList()};$$('[data-filter]',body).forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});drawList()}else{body.innerHTML=`<p class="proto-note">${objects.filter(o=>o.status==='Waiting').length} objects in limbo…</p><div class="proto-list"></div><button class="proto-btn" id="add-more">＋ Put an object here</button>`;$('#add-more').onclick=()=>{page='add';render()};drawList()}}
let selected='';function drawList(){const list=$('.proto-list',root);const found=objects.filter(o=>page==='home'?o.status==='Waiting':o.status!=='Waiting'&&(filter==='All'||o.status===filter)&&(o.name+' '+o.story).toLowerCase().includes(query.toLowerCase()));list.innerHTML=found.length?found.map(o=>`<button class="proto-card" data-id="${esc(o.id)}">${o.photo?`<img src="${esc(o.photo)}" alt="">`:'<span style="font-size:45px;padding:15px;color:#c89e91">◒</span>'}<div><h4>${esc(o.name)}</h4><small>${esc(o.status)}</small><p>${esc(o.story.slice(0,42))}…</p></div></button>`).join(''):'<p class="proto-note">这里还没有故事。可以回到等待室，为物品选择下一段旅程。</p>';$$('[data-id]',list).forEach(b=>b.onclick=()=>{selected=b.dataset.id;page='detail';render()})}render();
